"""Full-stage ranking using unchanged reach-fulfillment v0.1 definition."""
import csv,json,os,sqlite3,sys
from pathlib import Path
SQL="WITH\r\nparams AS (\r\n  SELECT NULL AS start_year, NULL AS stage\r\n),\r\nselected_games AS MATERIALIZED (\r\n  SELECT g.id AS game_id\r\n  FROM game g\r\n  JOIN season_stage ss ON ss.id=g.season_stage_id\r\n  JOIN league_season ls ON ls.id=ss.league_season_id\r\n  CROSS JOIN params cfg\r\n  WHERE (cfg.start_year IS NULL OR ls.start_year=cfg.start_year)\r\n    AND (cfg.stage IS NULL OR ss.stage=cfg.stage)\r\n),\r\naccepted_reaches AS MATERIALIZED (\r\n  SELECT r.event_id AS reach_event_id,\r\n         r.actor_player_id AS player_id,\r\n         e.kyoku_id,\r\n         e.event_order AS reach_order,\r\n         k.game_id\r\n  FROM reach_event r\r\n  JOIN event e ON e.id=r.event_id\r\n  JOIN kyoku k ON k.id=e.kyoku_id\r\n  JOIN selected_games sg ON sg.game_id=k.game_id\r\n  WHERE r.is_accepted=1\r\n),\r\nwinning_events AS MATERIALIZED (\r\n  SELECT a.actor_player_id AS player_id,\r\n         e.kyoku_id,\r\n         e.event_order AS win_order,\r\n         e.type AS win_type\r\n  FROM agari_event a\r\n  JOIN event e ON e.id=a.event_id\r\n  JOIN kyoku k ON k.id=e.kyoku_id\r\n  JOIN selected_games sg ON sg.game_id=k.game_id\r\n  WHERE e.type IN ('tsumo','ron')\r\n),\r\nreach_outcomes AS (\r\n  SELECT r.reach_event_id,\r\n         r.player_id,\r\n         MAX(CASE WHEN w.win_type='tsumo' THEN 1 ELSE 0 END) AS tsumo_success,\r\n         MAX(CASE WHEN w.win_type='ron' THEN 1 ELSE 0 END) AS ron_success\r\n  FROM accepted_reaches r\r\n  LEFT JOIN winning_events w\r\n    ON w.kyoku_id=r.kyoku_id\r\n   AND w.player_id=r.player_id\r\n   AND w.win_order>r.reach_order\r\n  GROUP BY r.reach_event_id,r.player_id\r\n),\r\nby_player AS (\r\n  SELECT player_id,\r\n         COUNT(*) AS accepted_reaches,\r\n         SUM(CASE WHEN tsumo_success=1 OR ron_success=1 THEN 1 ELSE 0 END) AS fulfilled_reaches,\r\n         SUM(tsumo_success) AS tsumo_fulfilled,\r\n         SUM(ron_success) AS ron_fulfilled\r\n  FROM reach_outcomes\r\n  GROUP BY player_id\r\n)\r\nSELECT p.id AS player_id,\r\n       p.name AS player_name,\r\n       b.accepted_reaches,\r\n       b.fulfilled_reaches,\r\n       b.tsumo_fulfilled,\r\n       b.ron_fulfilled,\r\n       ROUND(100.0*b.fulfilled_reaches/NULLIF(b.accepted_reaches,0),2) AS reach_success_pct,\r\n       ROUND(100.0*b.tsumo_fulfilled/NULLIF(b.accepted_reaches,0),2) AS reach_tsumo_pct,\r\n       ROUND(100.0*b.ron_fulfilled/NULLIF(b.accepted_reaches,0),2) AS reach_ron_pct\r\nFROM by_player b\r\nJOIN player p ON p.id=b.player_id\r\nORDER BY reach_success_pct DESC,b.fulfilled_reaches DESC,b.accepted_reaches DESC,p.name"
con=sqlite3.connect("file:"+os.path.abspath(sys.argv[1])+"?mode=ro",uri=True)
con.row_factory=sqlite3.Row
rows=[dict(r) for r in con.execute(SQL)]
if not rows: raise RuntimeError("No reach results")
out=Path("results");out.mkdir(exist_ok=True)
with (out/"reach_fulfillment_all.csv").open("w",encoding="utf-8-sig",newline="") as f:
 w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
(out/"reach_fulfillment_top10.json").write_text(json.dumps(rows[:10],ensure_ascii=False,indent=2),encoding="utf-8")
print("players",len(rows),"accepted",sum(r["accepted_reaches"] for r in rows),"fulfilled",sum(r["fulfilled_reaches"] for r in rows),flush=True)
print("TOP10",json.dumps(rows[:10],ensure_ascii=False,indent=2),flush=True)
